  "elevation": [
    {
      "style": "rgba(20, 24, 28, 0.125) 0px 0px 1px 1px inset",
      "element": "Cards and content blocks"
    },
    {
      "style": "rgba(0, 0, 0, 0.25) 0px 1px 5px 0px, rgba(0, 0, 0, 0.35) 0px 1px 10px 0px",
      "element": "Dropdowns and overlays"
    },
    {
      "style": "rgba(221, 238, 255, 0.25) 0px 0px 0px 1px inset",
      "element": "Focus and active rings"
    },
    {
      "style": "rgba(255, 255, 255, 0.1) 0px 1px 0px 0px inset",
      "element": "Button inner highlight"
    }
  ],
  "elevationPhilosophy": "Depth is created through surface color shifts and 1px inset borders, not through cast shadows. The palette's tightly spaced neutrals (#14181c → #202830 → #2c3440) carry the layering. The only cast shadows appear on floating elements like modals and tooltips, keeping the default page flat and quiet.",
  "imagery": "Photography is the dominant visual language: large cinematic stills serve as hero backgrounds (full-bleed, edge-to-edge, with dark overlay for text legibility), while film poster artwork populates grid layouts in 2:3 portrait orientation. Posters have no frames, shadows, or rounded corners — they sit directly on the dark canvas, letting the artwork itself provide visual weight. No illustrations, no 3D renders, no abstract graphics. Image treatment is natural and unmanipulated: full color, ungraded, presented as-is. Iconography is minimal and outlined: thin 1px strokes in Fog or Pewter, with star icons as the only filled glyphs (in acid green). The visual hierarchy is: photographic hero → poster grid → editorial text blocks. Imagery occupies roughly 40% of the above-fold real estate and 60% in content sections.",
  "layout": "Full-bleed dark canvas with centered max-width content containers (1200px). The hero pattern is a full-viewport-width photographic banner with a dark gradient overlay, centered headline in serif, and a single acid-green CTA button — no split layouts, no side-by-side hero variants. Below the fold, content flows in alternating bands: a horizontal poster strip, then a text+grid section, then another poster grid. The masonry/grid layout is the primary content arrangement, with 6–8 columns of film posters separated by 7px gaps. Sections are separated by vertical space (64px) rather than visible dividers — the dark background absorbs boundaries. Navigation is a persistent top bar at full width, sticky on scroll. The overall rhythm is: wide hero → dense grid → editorial text block → dense grid → footer, with consistent 64px breathing room between sections.",
  "customSections": [
    {
      "title": "Agent Prompt Guide",
      "content": "$1e"
    },
    {
      "title": "Type Pairing Philosophy",
      "content": "The two-typeface system is a functional boundary, not a stylistic choice. Graphik is the product: it handles everything from nav to buttons to metadata, and its wide-tracked uppercase treatment gives the chrome a printed, intentional feel. Tiempos is the editorial: it appears only where the content becomes reading — reviews, log entries, descriptions. This boundary must stay sharp. Never set Tiempos in navigation. Never set Graphik in body paragraphs. The moment the fonts bleed into each other's territory, the product loses its identity as half-tool, half-magazine."
    }
  ],
  "similar": [
    {
      "why": "Same dark cinema-lobby atmosphere with a single saturated accent color and serif/sans type pairing for editorial film content",
      "business": "Mubi"
    },
    {
      "why": "Identical dark-mode interface with poster-grid content, similar compact sans-serif chrome, and the same graphik-like geometric proportions",
